-- Hand-written: client currency lock, anonymised-contact freeze and state-code check (M3.3), generated by scripts/write-triggers.ts from src/triggers.ts.
CREATE TRIGGER `clients_currency_locked` BEFORE UPDATE OF currency ON `clients` WHEN NEW.currency IS NOT OLD.currency AND EXISTS (SELECT 1 FROM documents WHERE client_id = OLD.id AND type IN ('proforma', 'tax_invoice', 'export_invoice', 'credit_note', 'debit_note', 'receipt', 'receipt_voucher', 'refund_voucher')) BEGIN SELECT RAISE(ABORT, 'currency is locked: the client has an invoice'); END;
--> statement-breakpoint
CREATE TRIGGER `contacts_anonymised_frozen` BEFORE UPDATE ON `contacts` WHEN OLD.anonymised_at IS NOT NULL BEGIN SELECT RAISE(ABORT, 'an anonymised contact cannot change'); END;
--> statement-breakpoint
CREATE TRIGGER `clients_state_check_insert` BEFORE INSERT ON `clients` WHEN (NEW.gst_status IN ('registered', 'unregistered') AND (NEW.state_code IS NULL OR NOT (NEW.state_code GLOB '[0-9][0-9]'))) OR (NEW.gst_status = 'overseas' AND NEW.state_code IS NOT NULL) BEGIN SELECT RAISE(ABORT, 'a client in India needs a state code and an overseas client has none'); END;
--> statement-breakpoint
CREATE TRIGGER `clients_state_check_update` BEFORE UPDATE OF gst_status, state_code ON `clients` WHEN (NEW.gst_status IN ('registered', 'unregistered') AND (NEW.state_code IS NULL OR NOT (NEW.state_code GLOB '[0-9][0-9]'))) OR (NEW.gst_status = 'overseas' AND NEW.state_code IS NOT NULL) BEGIN SELECT RAISE(ABORT, 'a client in India needs a state code and an overseas client has none'); END;
